package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// templatesProvider is the request-independent source for the template
// endpoints: the library release list, show and create all fetch and render
// against. Resolving it once per server keeps the release the form was filled
// against and the release the run renders from the same — a latest-release
// lookup per request could drift between the two.
type templatesProvider struct {
	version   string
	userAgent string

	// Test overrides; production leaves these zero-valued and gets the
	// official library.
	owner  string
	repo   string
	source template.SourceOptions
}

// fetchLibrary resolves and checks out the provider's library release. tag
// pins the release the server has already resolved, so only the first fetch
// of a process pays a latest-release lookup; an explicitly configured version
// still wins, because pinning is the caller's decision, not the cache's.
func (p templatesProvider) fetchLibrary(ctx context.Context, tag string) (*template.Library, error) {
	version := p.version
	if version == "" {
		version = tag
	}
	return template.FetchLibrary(ctx, template.LibraryOptions{
		Version:   version,
		UserAgent: p.userAgent,
		Owner:     p.owner,
		Repo:      p.repo,
		Source:    p.source,
	})
}

// fetchLibrary serves every template endpoint, resolving the library release
// once per process and reusing it after: the release a form is filled against
// and the release its run renders from can then never differ, and a form's
// suggestion refreshes cost no GitHub requests at all.
//
// The lock spans the fetch rather than just the tag read. A cold cache means
// a clone, and letting concurrent requests each start one would be the
// thundering herd the cache exists to prevent — the same bargain topoMu makes
// for the hosts' graph verbs. Once warm, every fetch is a local read.
func (s *apiServer) fetchLibrary(ctx context.Context) (*template.Library, error) {
	s.tagMu.Lock()
	defer s.tagMu.Unlock()
	lib, err := s.templates.fetchLibrary(ctx, s.tag)
	if err != nil {
		return nil, err
	}
	// Whatever release the fetch settled on is the one the process holds,
	// including a tag the offline fallback chose rather than the latest.
	s.tag = lib.Version
	return lib, nil
}

// libraryTag returns the release every template render pins to, resolving it
// on first use like fetchLibrary does. Handlers that hand a version to another
// package need the tag itself rather than a Library — without it those renders
// would resolve their own, which is the per-request lookup this cache exists
// to remove.
func (s *apiServer) libraryTag(ctx context.Context) (string, error) {
	lib, err := s.fetchLibrary(ctx)
	if err != nil {
		return "", err
	}
	defer lib.Close()
	return lib.Version, nil
}

// refreshTemplates drops the resolved release so the next fetch resolves the
// latest one again, then serves the fresh listing. It is how a template
// release cut while the dashboard runs is picked up without a restart —
// the same escape hatch POST /api/topology/refresh offers.
func (s *apiServer) refreshTemplates(w http.ResponseWriter, r *http.Request) {
	s.tagMu.Lock()
	s.tag = ""
	s.tagMu.Unlock()
	s.listTemplates(w, r)
}

// createRequest is the POST /api/templates/{name}/create body.
type createRequest struct {
	// Name folds into values.name when the caller did not set it directly
	// (the CLI's --name sugar) and defaults the output directory:
	// kebab-cased, under Dir. Empty means the resolved "name" parameter
	// decides the directory instead — the no-prompt default both surfaces
	// prefer.
	Name string `json:"name"`

	// Dir is the root-relative, slash-separated directory the output renders
	// under; "" or "." is the workspace root — the pre-Dir behavior. It must
	// already exist: the endpoint scaffolds into systems, it does not invent
	// directory trees.
	Dir string `json:"dir,omitempty"`

	// Values are the template parameters, as --set would supply them.
	Values map[string]any `json:"values"`

	// Force allows rendering into a non-empty output directory.
	Force bool `json:"force,omitempty"`
}

// createResponse is the 201 payload: CreateResult with the output directory
// made root-relative, matching the identifier space /api/integrations uses.
type createResponse struct {
	*template.CreateResult
	// Diagnostics is what the render wrote to stderr, one entry per line —
	// the fetch notice and each dependency render. Provenance, not failure.
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// maxCreateBodyBytes caps a create request body. Parameter values are short
// scalars; a megabyte is already generous and keeps a malformed client from
// streaming unbounded input into memory.
const maxCreateBodyBytes = 1 << 20

// templateSummary is one list entry with the manifest metadata the create
// surfaces filter on — notably the intropy.io/* labels a flow-view slot
// selects templates by. Additive beside the bare names `templates` keeps.
type templateSummary struct {
	Name        string            `json:"name"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
}

// listTemplates mirrors `template list -o json` against the server's library
// release, adding per-template metadata (`entries`) on top of the names. The
// describes are local reads on the library checkout; one malformed manifest
// drops that entry rather than hiding the rest of the library.
func (s *apiServer) listTemplates(w http.ResponseWriter, r *http.Request) {
	lib, err := s.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	names, err := lib.List()
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	entries := make([]templateSummary, 0, len(names))
	for _, name := range names {
		desc, err := lib.Describe(name)
		if err != nil {
			continue
		}
		entries = append(entries, templateSummary{
			Name:        name,
			Title:       desc.Title,
			Description: desc.Description,
			Labels:      desc.Labels,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"owner":     lib.Owner,
		"repo":      lib.Repo,
		"version":   lib.Version,
		"templates": names,
		"entries":   entries,
	})
}

// getTemplate mirrors `template show -o json` for one template, adding the
// ordered field list the form renders from. The optional ?dir query names a
// root-relative directory the way createRequest.Dir does; when present, each
// field gains the parameter suggestions the workspace under it implies —
// the same candidates `int create` would prompt with there. Without it the
// response is context-free and suggestion-free.
func (s *apiServer) getTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	lib, err := s.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	result, err := lib.Describe(name)
	if err != nil {
		writeError(w, templateFetchStatus(err), err.Error())
		return
	}

	if dir := r.URL.Query().Get("dir"); dir != "" {
		confirmed, err := parseConfirmedQuery(r.URL.Query())
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		if err := s.suggestForDir(result, dir, confirmed); err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
	}
	writeJSON(w, http.StatusOK, result)
}

// getTemplateSuggestions serves only the suggestion lists of a dir-scoped
// detail: the refresh a form issues when an answered parameter changes what
// the workspace implies for the rest (a picked topic narrows the contract
// candidates). It is the same computation getTemplate runs, without the
// library fetch — a mid-form refresh must never swap the manifest the form
// was filled against.
func (s *apiServer) getTemplateSuggestions(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	lib, err := s.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

	result, err := lib.Describe(name)
	if err != nil {
		writeError(w, templateFetchStatus(err), err.Error())
		return
	}

	dir := r.URL.Query().Get("dir")
	if dir == "" {
		writeError(w, http.StatusBadRequest, "dir is required (suggestions derive from the workspace under it)")
		return
	}
	confirmed, err := parseConfirmedQuery(r.URL.Query())
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	if err := s.suggestForDir(result, dir, confirmed); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	suggestions := make(map[string][]string, len(result.Fields))
	for _, f := range result.Fields {
		suggestions[f.Name] = f.Suggestions
	}
	writeJSON(w, http.StatusOK, map[string]any{"suggestions": suggestions})
}

// suggestForDir populates each field's suggestions from the workspace under
// dir, chained off the values the form has already confirmed — the same
// inputs `int create` prompts with (workspace facts plus confirmed values).
func (s *apiServer) suggestForDir(result *template.DescribeResult, dir string, confirmed map[string]any) error {
	facts, err := s.factsForDir(dir)
	if err != nil {
		return err
	}
	facts.SetMessageParameters(messageParametersFromLabels(result.Labels))
	facts.SetWiringDirection(template.MessageDirection(result.Labels[template.TemplateBlockKindLabel]))
	suggestions := template.Suggest(result.Fields, facts, confirmed)
	for i := range result.Fields {
		template.AttachSuggestions(&result.Fields[i], suggestions)
	}
	return nil
}

func messageParametersFromLabels(labels map[string]string) []string {
	v := labels[template.TemplateMessageParamsLabel]
	if strings.TrimSpace(v) == "" {
		return nil
	}
	parts := strings.Split(v, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if name := strings.TrimSpace(p); name != "" {
			out = append(out, name)
		}
	}
	return out
}

// parseConfirmedQuery decodes the repeated `set` query parameter
// (?set=topic=orders&set=pubsub=events) into the confirmed-values map
// Suggest chains from. Values stay strings — prompt values do, too. A
// malformed pair is a 400: a silently dropped set would suggest candidates
// for the wrong workspace state.
func parseConfirmedQuery(q map[string][]string) (map[string]any, error) {
	pairs := q["set"]
	if len(pairs) == 0 {
		return nil, nil
	}
	confirmed := make(map[string]any, len(pairs))
	for _, pair := range pairs {
		name, value, ok := strings.Cut(pair, "=")
		if !ok || name == "" {
			return nil, fmt.Errorf("invalid set %q (expected name=value)", pair)
		}
		confirmed[name] = value
	}
	return confirmed, nil
}

// factsForDir validates a root-relative dir with the create endpoint's
// rules and indexes the scaffold records under it. The dir must exist —
// suggesting from a system means the system directory is there.
func (s *apiServer) factsForDir(dir string) (*template.WorkspaceFacts, error) {
	segments, err := splitCreateDir(dir)
	if err != nil {
		return nil, err
	}
	abs := filepath.Join(append([]string{s.root}, segments...)...)
	if info, statErr := os.Stat(abs); statErr != nil || !info.IsDir() {
		return nil, fmt.Errorf("directory %q does not exist under the workspace root", dir)
	}
	facts, _ := system.LoadWorkspaceFacts(abs)
	facts.SetOrganization(s.organization)
	return facts, nil
}

// createTemplate runs `int create` for one template: the form's values
// resolve non-interactively (a missing required parameter is a 422 naming
// it), the skeleton renders under the workspace root, and the result comes
// back as served. Runs are serialized: two concurrent renders of the same
// name would race on the output directory.
func (s *apiServer) createTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	if err := template.ValidateTemplateName(name); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	var req createRequest
	dec := json.NewDecoder(io.LimitReader(r.Body, maxCreateBodyBytes))
	if err := dec.Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}

	values, err := createValues(req)
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	s.createMu.Lock()
	defer s.createMu.Unlock()

	// The render pins the release the form was filled against, which is the
	// whole point of holding one: a create that resolved its own could render
	// from a release the user never saw.
	tag, err := s.libraryTag(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}

	prep, err := template.PrepareCreate(r.Context(), template.CreateOptions{
		Template:  name,
		Version:   tag,
		SetValues: values,
		UserAgent: s.templates.userAgent,
		Owner:     s.templates.owner,
		Repo:      s.templates.repo,
		Source:    s.templates.source,
	})
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	defer prep.Cleanup()

	outputDir, err := s.resolveCreateDir(req, prep)
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	var logs bytes.Buffer
	result, err := template.RunCreate(prep, outputDir, req.Force, &logs)
	if err != nil {
		writeError(w, createErrorStatus(err), err.Error())
		return
	}
	result.OutputDir = s.relPath(result.OutputDir)
	writeJSON(w, http.StatusCreated, createResponse{
		CreateResult: result,
		Diagnostics:  diagnosticLines(logs.String()),
	})
}

// createValues folds the request's name into the value set `int create
// --name` would produce: name doubles as values.name when the caller did
// not set it directly. When the template does not declare `name`, the
// value still lands there — the CLI's sugar does the same.
func createValues(req createRequest) (map[string]any, error) {
	values := req.Values
	if values == nil {
		values = map[string]any{}
	}
	if _, ok := values["name"]; !ok && req.Name != "" {
		values["name"] = req.Name
	}
	for key := range values {
		if isReservedValueKey(key) {
			return nil, fmt.Errorf("value %q is reserved and cannot be supplied", key)
		}
	}
	return values, nil
}

// resolveCreateDir picks the output directory, confined to the tree the
// dashboard serves so the endpoint can never write outside it. An explicit
// name kebab-cases under Dir (the workspace root when empty), as
// `int create --name` does; without a name the resolved "name" parameter
// kebab-cases the same way, and a template without one is the error
// --out-dir would have spared.
func (s *apiServer) resolveCreateDir(req createRequest, prep *template.PreparedCreate) (string, error) {
	segments, err := splitCreateDir(req.Dir)
	if err != nil {
		return "", err
	}
	parentDir := filepath.Join(append([]string{s.root}, segments...)...)
	if len(segments) > 0 {
		// The dir must already exist: creating into a system means the system
		// directory is there; anything else is a client mistake, not a mkdir.
		if info, statErr := os.Stat(parentDir); statErr != nil || !info.IsDir() {
			return "", fmt.Errorf("directory %q does not exist under the workspace root", req.Dir)
		}
	}

	name := req.Name
	if name == "" {
		v, ok := prep.Values["name"].(string)
		if !ok || v == "" {
			return "", errors.New("name is required (template declares no 'name' parameter to derive the directory from)")
		}
		name = v
	}
	leaf := xstrings.ToKebabCase(name)
	if strings.ContainsAny(leaf, `/\`) || leaf == "." || leaf == ".." {
		return "", fmt.Errorf("invalid output directory %q (must be a single path segment)", leaf)
	}

	rootAbs, err := filepath.Abs(s.root)
	if err != nil {
		return "", err
	}
	outputDir := filepath.Join(parentDir, leaf)
	outAbs, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	want := filepath.Join(append(append([]string{rootAbs}, segments...), leaf)...)
	if outAbs != want {
		return "", fmt.Errorf("invalid output directory %q (output would escape the workspace root)", leaf)
	}
	return outputDir, nil
}

// splitCreateDir validates a create request's dir and returns its segments.
// "" and "." mean the workspace root (no segments). Each segment must be a
// plain directory name — no separators besides "/", no dot entries, nothing
// hidden — so the joined path can only descend from the root.
func splitCreateDir(dir string) ([]string, error) {
	if dir == "" || dir == "." {
		return nil, nil
	}
	if strings.Contains(dir, `\`) {
		return nil, fmt.Errorf("invalid dir %q (must be slash-separated)", dir)
	}
	segments := strings.Split(dir, "/")
	for _, seg := range segments {
		if seg == "" || seg == ".." || strings.HasPrefix(seg, ".") {
			return nil, fmt.Errorf("invalid dir %q (each segment must be a plain directory name)", dir)
		}
	}
	return segments, nil
}

// isReservedValueKey reports whether key is one of the reserved value keys a
// caller injects after resolution (topology, component, …). Users never
// supply them — a form value under one would collide with InjectReserved's
// refusal, so the endpoint refuses first with a message that says why.
func isReservedValueKey(key string) bool {
	switch key {
	case template.ReservedTopologyKey,
		template.ReservedComponentKey,
		template.ReservedGitopsKey,
		template.ReservedScaffoldKey,
		template.ReservedEnvKey:
		return true
	}
	return false
}

// templateFetchStatus maps a library fetch failure to the status the client
// can act on: an unknown template is a 404, anything upstream is a 502.
func templateFetchStatus(err error) int {
	if strings.Contains(err.Error(), "not found in") {
		return http.StatusNotFound
	}
	return http.StatusBadGateway
}

// createErrorStatus maps a create failure to the status the form renders:
// unmet parameters and name conflicts are 422 (the form highlights fields),
// a non-empty output directory is 409 (the form offers force), and a fetch
// failure is 502. Everything else is a plain 500.
func createErrorStatus(err error) int {
	msg := err.Error()
	switch {
	case strings.Contains(msg, "not empty"):
		return http.StatusConflict
	case strings.Contains(msg, "missing required parameter"),
		strings.Contains(msg, "unknown parameter"),
		strings.Contains(msg, "not found in"):
		return http.StatusUnprocessableEntity
	case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
		return http.StatusBadGateway
	}
	return http.StatusInternalServerError
}
package system

import (
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check stays in Assemble, gated on the component's shape.
type parseBlock func(e template.ScaffoldEntry, c *Component) error

// blockParsers is the set of block kinds Assemble accepts. Records with a
// kind absent from the registry are skipped with a warning naming the
// supported kinds. Adding a kind is a constant, a parser, and an entry here.
var blockParsers = map[string]parseBlock{
	template.BlockKindExtractor:     parseExtractor,
	template.BlockKindGateway:       parseGateway,
	template.BlockKindLoader:        parseLoader,
	template.BlockKindTransactional: parseTransactional,
}

// supportedKinds lists the registry keys sorted, for the unsupported-kind
// warning.
func supportedKinds() []string {
	kinds := make([]string, 0, len(blockParsers))
	for k := range blockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// parseExtractor reads the one message an extractor publishes. The message
// identity is the declaration; system assembly derives the channel and
// payload type from it.
func parseExtractor(e template.ScaffoldEntry, c *Component) error {
	published, err := parsePublishes(e, c)
	if err != nil || !published {
		return err
	}
	return parseSinglePort(e, c)
}

// parseGateway reads a gateway: the message it publishes, as an extractor's,
// and the endpoint it exposes with its path. The endpoint is required — the
// template that introduced the kind always records it — and it is not a file
// port, so it stays out of Ports. The path defaults to /<message>, the default
// the framework applies to a record without one.
func parseGateway(e template.ScaffoldEntry, c *Component) error {
	published, err := parsePublishes(e, c)
	if err != nil {
		return err
	}
	endpoint, err := template.RecordValue(e, template.KeyPort)
	if err != nil {
		return err
	}
	c.Endpoint = endpoint
	if published {
		c.EndpointPath = "/" + c.Message.Name
	}
	if _, ok := e.Values[template.KeyEndpointPath]; ok {
		path, err := template.RecordValue(e, template.KeyEndpointPath)
		if err != nil {
			return err
		}
		if !strings.HasPrefix(path, "/") {
			return fmt.Errorf("%s: values.%s is %q; a path starts with /", e.Path, template.KeyEndpointPath, path)
		}
		c.EndpointPath = path
	}
	return nil
}

// parsePublishes reads the one message a producing block publishes and the
// channel it publishes on; false when the message derives no contract.
func parsePublishes(e template.ScaffoldEntry, c *Component) (bool, error) {
	message, err := template.ReadPublishesMessage(e)
	if err != nil {
		return false, preScalarMessageRecord(err)
	}
	contract := template.PascalCase(message)
	if contract == "" {
		return false, nil
	}
	channel, err := template.ReadChannel(e)
	if err != nil {
		return false, err
	}
	if channel == "" {
		channel = message
	}
	c.channel = channel
	c.Topic = &TopicKey{Name: channel}
	c.topicContract = contract
	c.Message = &MessageWiring{Kind: MessagePublish, Name: message, Contract: contract}
	return true, nil
}

// parseLoader reads the messages a loader routes — its routes, or the one
// message a record without routes subscribes to — what it does with the rest
// of its topic, and the topic it declares. Assembly checks every routed
// message's producer publishes on that topic and fails if one does not.
func parseLoader(e template.ScaffoldEntry, c *Component) error {
	routes, err := template.ReadRoutes(e)
	if err != nil {
		if _, routed := e.Values[template.KeyRoutes]; routed {
			return err
		}
		return preScalarMessageRecord(err)
	}
	if c.Default, err = template.ReadDefault(e); err != nil {
		return err
	}
	if c.channel, err = template.ReadChannel(e); err != nil {
		return err
	}
	c.Routes = routes
	// The pipeline's message is subscribes; a record routing without it
	// predates the key and is typed by its first route.
	message, ok := template.SoftValue(e.Values, template.KeySubscribes)
	if !ok {
		message = routes[0].Message
	}
	c.Message = &MessageWiring{Kind: MessageSubscribe, Name: message}
	return parseSinglePort(e, c)
}

// preScalarMessageRecord reports a message-wiring read failure as the
// migration it is: a record scaffolded before the scalar message DSL carries
// nested blocks or legacy flat keys, and no fallback reads them. The guidance
// names both migration paths — set the scalar key, or re-scaffold.
func preScalarMessageRecord(err error) error {
	return fmt.Errorf("%w\nthis record predates the scalar message DSL: set values.publishes (extractor, gateway) or values.subscribes (loader) to the message name in the record's values, or re-scaffold the integration with a current template release", err)
}

func parseSinglePort(e template.ScaffoldEntry, c *Component) error {
	if _, ok := e.Values[template.KeyPort]; ok {
		port, err := template.RecordValue(e, template.KeyPort)
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// parseTransactional parses the wiring of a transactional block: exactly
// two ports, From before To, and no message. Both ports are required — a
// half-wired transactional block would render broken code.
func parseTransactional(e template.ScaffoldEntry, c *Component) error {
	from, err := template.RecordValue(e, template.KeyFromPort)
	if err != nil {
		return err
	}
	to, err := template.RecordValue(e, template.KeyToPort)
	if err != nil {
		return err
	}
	c.Ports = []string{from, to}
	return nil
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
  type TemplateSummary,
} from '../api'
import { Combobox } from './Combobox'
import { Field, FormField } from './form'
import { useTemplateFields } from './useTemplateFields'

/** The create placeholders on the flow canvas, by archetype column:
 *  in (extractor, gateway) → process → out. */
export type SlotKind = 'extractor' | 'gateway' | 'transactional' | 'loader'

// The intropy.io/block-kind label value each slot filters templates by.
const KIND_BLOCK_LABEL: Record<SlotKind, string> = {
  extractor: 'extractor',
  gateway: 'gateway',
  transactional: 'transactional-integration',
  loader: 'loader',
}

const KIND_TITLE: Record<SlotKind, string> = {
  extractor: 'extractor',
  gateway: 'gateway',
  transactional: 'core block',
  loader: 'loader',
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'error'; message: string; status: number }

// norm compares label values the way dataFlowFor compares kinds: ignoring
// case and hyphens, so "transactional-integration" matches however the
// library spells it.
const norm = (s: string) => s.toLowerCase().replace(/-/g, '')

interface Props {
  kind: SlotKind
  /** Root-relative directory the new block scaffolds into ("." = workspace root). */
  systemPath: string
  systemLabel: string
  onClose: () => void
  /** Called with the created scaffold's root-relative path — the caller
   *  refreshes /api/flow so the new block appears as a ghost node. */
  onCreated: (outputDir: string) => void
}

// CreateDrawer is the flow view's create surface: opened by a placeholder
// slot, it offers the library's templates for that block kind and renders the
// selected one's manifest as the same form the templates view uses, scoped to
// the slot's system. Success is reported to the caller — the drawer closes
// and the canvas shows the new scaffold as a ghost node.
export function CreateDrawer({ kind, systemPath, systemLabel, onClose, onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [showAll, setShowAll] = useState(false)
  const [tpl, setTpl] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  const candidates = useMemo<TemplateSummary[]>(() => {
    if (!list) return []
    const entries: TemplateSummary[] =
      list.entries ?? list.templates.map((name) => ({ name }))
    if (showAll) return entries
    const want = norm(KIND_BLOCK_LABEL[kind])
    return entries.filter((e) => norm(e.labels?.['intropy.io/block-kind'] ?? '') === want)
  }, [list, showAll, kind])

  // Keep the selection valid as the candidate list settles (load, show-all).
  useEffect(() => {
    setTpl((cur) =>
      cur && candidates.some((c) => c.name === cur) ? cur : candidates[0]?.name ?? null,
    )
  }, [candidates])

  return (
    <aside className="create-drawer">
      <header className="create-drawer-head">
        <div>
          <h2 className="create-drawer-title">New {KIND_TITLE[kind]}</h2>
          <span className="create-drawer-sys">in {systemLabel}</span>
        </div>
        <button type="button" className="flow-detail-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </header>

      {listError && <div className="banner error">{listError}</div>}
      {!list && !listError && <div className="empty">loading templates…</div>}

      {list && candidates.length === 0 && (
        <div className="empty">
          no template in {list.owner}/{list.repo}@{list.version} carries{' '}
          <code>intropy.io/block-kind: {KIND_BLOCK_LABEL[kind]}</code>
          <div>
            <button type="button" className="flow-refresh" onClick={() => setShowAll(true)}>
              show all templates
            </button>
          </div>
        </div>
      )}

      {list && candidates.length > 0 && (
        <>
          <Field label="template" required>
            <Combobox
              value={tpl}
              options={candidates.map((c) => ({
                value: c.name,
                label: c.title ? `${c.title} (${c.name})` : c.name,
              }))}
              onChange={setTpl}
              placeholder="Select a template…"
            />
          </Field>
          {!showAll && (
            <button
              type="button"
              className="drawer-show-all"
              onClick={() => setShowAll(true)}
            >
              show all templates
            </button>
          )}
          {tpl && (
            <DrawerForm
              key={tpl}
              template={tpl}
              systemPath={systemPath}
              onCreated={onCreated}
            />
          )}
        </>
      )}
    </aside>
  )
}

// DrawerForm mirrors the templates view's TemplatePanel: manifest fetched,
// defaults seeded, required fields tracked, force offered on a 409. It is
// keyed by template name so switching templates resets all form state. The
// differences: the output directory is locked under the slot's system, and
// success closes the drawer instead of rendering a result card.
function DrawerForm({
  template,
  systemPath,
  onCreated,
}: {
  template: string
  systemPath: string
  onCreated: Props['onCreated']
}) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const { values, setValue, visible, optional, missing } = useTemplateFields(
    detail?.fields ?? [],
    { template, dir: systemPath },
  )
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [force, setForce] = useState(false)
  const [create, setCreate] = useState<CreateState>({ phase: 'idle' })

  useEffect(() => {
    api
      .getTemplate(template, systemPath)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [template, systemPath])

  const run = useCallback(() => {
    setCreate({ phase: 'running' })
    // No name: the resolved "name" parameter kebab-cases into the
    // directory, confined inside the slot's system directory server-side.
    api
      .createTemplate(template, { dir: systemPath, values, force })
      .then((result: CreateResponse) => onCreated(result.outputDir))
      .catch((e: unknown) => {
        const err = e as { message?: string; status?: number }
        setCreate({ phase: 'error', message: errText(e), status: err.status ?? 0 })
      })
  }, [template, systemPath, values, force, onCreated])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!detail) {
    return <div className="empty">loading {template}…</div>
  }

  const canRun = missing.length === 0 && create.phase !== 'running'
  const prefix = systemPath === '.' ? '' : `${systemPath}/`

  return (
    <form
      className="template-form"
      onSubmit={(e) => {
        e.preventDefault()
        if (canRun) run()
      }}
    >
      {detail.description && <p className="template-desc">{detail.description}</p>}

      {prefix && <p className="form-hint">scaffolds under {prefix}</p>}

      {visible.map((f) => (
        <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
      ))}

      {missing.length > 0 && (
        <div className="form-hint">missing required: {missing.join(', ')}</div>
      )}

      {optional.length > 0 && (
        <>
          <button
            type="button"
            className="advanced-toggle"
            onClick={() => setShowAdvanced((s) => !s)}
          >
            {showAdvanced ? '▾' : '▸'} advanced ({optional.length})
          </button>
          {showAdvanced &&
            optional.map((f) => (
              <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
            ))}
        </>
      )}

      {create.phase === 'error' && create.status === 409 && (
        <label className="force-row">
          <input type="checkbox" checked={force} onChange={(e) => setForce(e.target.checked)} />
          render into the non-empty directory anyway
        </label>
      )}

      <div className="form-actions">
        <button type="submit" className="run-btn" disabled={!canRun}>
          {create.phase === 'running' ? 'scaffolding…' : 'Scaffold'}
        </button>
      </div>

      {create.phase === 'error' && <div className="banner error">{create.message}</div>}
    </form>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}
