const GROUP_HEADER = 44
const GROUP_PAD = 20
const INFRA_W = 200
const INFRA_H = 76
const EXT_W = 184
const EXT_H = 72
const EXT_GAP = 96
const EXT_VGAP = 24

const WORKSPACE_KEY = '__workspace__'

/** Which way data crosses the system boundary for a component. */
type DataFlow = 'in' | 'out' | 'both' | 'internal'

// Boundary direction by declared component kind, used only to pick the card's
// directional glyph — never to invent wiring; every edge on the canvas comes
// from the declared topology.
const KIND_DATA_FLOW: Record<string, DataFlow> = {
  extractor: 'in',
  gateway: 'in',
  loader: 'out',
  transactional: 'both',
  transactionalintegration: 'both',
  aggregator: 'internal',
}

// dataFlowFor resolves a component kind to its boundary direction, ignoring
// case and hyphens (the topology library kebab-cases kinds, e.g.
// "transactional-integration").
function dataFlowFor(kind: string): DataFlow | undefined {
  return KIND_DATA_FLOW[kind.toLowerCase().replace(/-/g, '')]
}

// seedsFiles tells whether a component takes test files: an inbound block that
// sweeps a dev folder. A gateway is inbound too, but its items are pushed to
// it over HTTP — it has no folder to seed.
function seedsFiles(kind: string | undefined, flow: DataFlow | undefined): boolean {
  return flow === 'in' && kind?.toLowerCase() !== 'gateway'
}

// Directional glyph per data flow; integrations with no known flow keep the
// generic chip icon rather than guessing a direction.
const DATA_FLOW_ICONS: Record<DataFlow, typeof MemoryIcon> = {
  in: InputIcon,
  out: OutputIcon,
  both: SyncAltIcon,
  internal: CycleIcon,
}

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  dataFlow?: DataFlow
  selected: boolean
  /** Cron expression badge for schedule-triggered components (declared topology only). */
  trigger?: string
  /** Scaffolded but not in the declared topology yet — rendered muted/dashed
   *  until `sys create` re-assembles the host and the topology is refreshed. */
  ghost?: boolean
  /** The node offers test-file seeding. Set at graph build: 'ready' for a
   *  declared extractor (the seed drawer resolves ports and dev folders),
   *  'ghost' for a scaffolded one (identified as an extractor but without
   *  declared wiring to seed against — a disabled, explained button). */
  seed?: 'ready' | 'ghost'
}

interface SlotNodeData extends Record<string, unknown> {
  kind: SlotKind
}

interface GroupNodeData extends Record<string, unknown> {
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  // At least three columns, so the create slots always sit in their archetype
  // positions (in → process → out) even when the declared graph is narrower —
  // an empty system renders as the fillable slot skeleton.
  const effCols = Math.max(cols, 3)
  const extractorCol = 0
  const loaderCol = Math.max(2, cols - 1)
  const transactionalCol = Math.min(loaderCol - 1, Math.max(1, Math.round(loaderCol / 2)))
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + effCols * NODE_W + (effCols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'

  // Scaffolded-but-undeclared components: blocks whose scaffold record lives
  // in this system but whose name the declared topology does not carry —
  // brand new (pre `sys create`) or renamed. They render as ghosts in their
  // block kind's column, wireless, until the host declares them.
  const declaredPaths = new Set(
    comps.map((c) => scaffoldPath(c.name) ?? joinProject(topo.path, c.name)),
  )
  const ghosts = items.filter((it) => !declaredPaths.has(it.path))
  const ghostCol = (g: IntegrationDetail): number => {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    return flow === 'in' ? extractorCol : flow === 'out' ? loaderCol : transactionalCol
  }

  // Placeholder slots, pinned to a shared bottom rail below the flow: one per
  // kind column, and the inbound column stacks its second entry kind, the
  // gateway, under the extractor. Clicking one opens the create drawer
  // pre-filtered to that block kind; the slots are affordances, never part of
  // the graph.
  const slotDefs: Array<{ kind: SlotKind; col: number; row: number }> = [
    { kind: 'extractor', col: extractorCol, row: 0 },
    { kind: 'gateway', col: extractorCol, row: 1 },
    { kind: 'transactional', col: transactionalCol, row: 0 },
    { kind: 'loader', col: loaderCol, row: 0 },
  ]

  // Column stacks center vertically against the tallest column: a lone
  // extractor sits level with the middle of the loader stack (and the topic
  // centered between them) instead of hugging the top, and the stack grows
  // out from the middle as blocks are added. Centering needs each column's
  // row count up front — the stack's height decides its starting offset.
  // Slots never count: they pin to the bottom rail (below), so they must not
  // push their column's stack off centre.
  const colRows: number[] = new Array<number>(effCols).fill(0)
  for (const c of comps) colRows[depth.get(`component:${c.name}`) ?? 0]++
  for (const [tid] of topicRefs) colRows[depth.get(tid) ?? 0]++
  for (const g of ghosts) colRows[ghostCol(g)]++
  const maxRows = Math.max(1, ...colRows)

  const rowsInCol: number[] = new Array<number>(effCols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    const offset = ((maxRows - colRows[d]) * (NODE_H + ROW_GAP)) / 2
    return { x: colX(d), y: contentTop + offset + row * (NODE_H + ROW_GAP), row }
  }

  // Component positions, keyed by ref, so externals can anchor to the
  // component they touch instead of the far edge of the canvas.
  const compPos = new Map<string, { x: number; y: number; col: number }>()
  for (const c of comps) {
    const ref = `component:${c.name}`
    const col = depth.get(ref) ?? 0
    const pos = place(col)
    compPos.set(ref, { x: pos.x, y: pos.y, col })
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.kind,
        dataFlow: dataFlowFor(c.kind),
        selected: false,
      } satisfies IntNodeData,
    })
  }

  // Vertical centering per topic: the average card-centre y of the
  // components wired to it, minus the topic's own half height. A topic's
  // place is between its publisher and subscribers, not on a row of its own.
  const topicY = new Map<string, number>()
  for (const [tid] of topicRefs) {
    const neighbours = comps
      .filter(
        (c) =>
          (c.publishes ?? []).some((p) => topicId(p.pubsub, p.topic) === tid) ||
          (c.subscribes ?? []).some((s) => topicId(s.pubsub, s.topic) === tid),
      )
      .map((c) => compPos.get(`component:${c.name}`))
      .filter((p): p is { x: number; y: number; col: number } => p !== undefined)
    if (neighbours.length === 0) continue
    const centre =
      neighbours.reduce((sum, p) => sum + p.y + NODE_H / 2, 0) / neighbours.length
    topicY.set(tid, centre - INFRA_H / 2)
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const contracts = topicContracts(topo, ref.pubsub, ref.topic)
    const carried = topicMessages(topo, ref.pubsub, ref.topic)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      // Rows share them across the topic's neighbours, so centre vertically
      // on the average of the wired components rather than taking the row.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: topicY.get(tid) ?? pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: contracts.length > 1 ? `${carried.length} messages` : contracts[0],
        detail: carried.length > 0 ? carried.map((m) => `${m.name} · ${m.contract ?? '—'}`).join('\n') : undefined,
      } satisfies TopicNodeData,
    })
  }

  for (const g of ghosts) {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    const pos = place(ghostCol(g))
    nodes.push({
      id: g.path,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: g.name,
        template: g.blockKind || g.template,
        dataFlow: flow,
        selected: false,
        ghost: true,
      } satisfies IntNodeData,
    })
  }

  // The slot rail: one shared baseline below the deepest node, so the slots
  // align across columns instead of drifting with each column's stack. An
  // empty system has no node bottom — the rail is the content top.
  const nodeBottom = Math.max(
    0,
    ...colRows.map((rows) =>
      rows === 0
        ? 0
        : contentTop +
          ((maxRows - rows) * (NODE_H + ROW_GAP)) / 2 +
          (rows - 1) * (NODE_H + ROW_GAP) +
          NODE_H,
    ),
  )
  const slotY = nodeBottom === 0 ? contentTop : nodeBottom + ROW_GAP
  for (const s of slotDefs) {
    nodes.push({
      id: `slot:${s.kind}`,
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: colX(s.col), y: slotY + s.row * (NODE_H + ROW_GAP) },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind } satisfies SlotNodeData,
    })
  }

  const slotRows = Math.max(...slotDefs.map((s) => s.row)) + 1
  const groupHeight = slotY + slotRows * NODE_H + (slotRows - 1) * ROW_GAP + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// SlotNode is a create placeholder: one per block kind, low-contrast
// until hovered. Clicking it opens the create drawer for that kind. It has no
// handles — a slot carries no wiring.
const SLOT_LABELS: Record<SlotKind, string> = {
  extractor: 'Extractor',
  gateway: 'Gateway',
  transactional: 'Core block',
  loader: 'Loader',
}

